    ('9910d3da-4875-49eb-8da4-3f2db69a48a6'::uuid, 'site_type', 'Temple', 'Temple complex', 'fields-wd1-2026-09-26d-s014-rollback:9910d3da-4875-49eb-8da4-3f2db69a48a6:site_type', 'rollback of fields-wd1-2026-09-26d-s014: site_type ''Temple complex'' restored on Qasr al-Sagha', '[{"source": "https://www.megalithic.co.uk/article.php?sid=37057", "url": "https://www.megalithic.co.uk/article.php?sid=37057", "quote": "is a small uninscribed temple known locally as Qasr el-Sagha, thought to be dedicated to Sobek the Crocodile God.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Qasr_el-Sagha", "url": "https://de.wikipedia.org/wiki/Qasr_el-Sagha", "quote": "Der Tempel besteht aus einer breiten Halle und besitzt sieben Naoi. Die hier verehrten Gottheiten sind unbekannt.", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "The Megalithic Portal (point 29.595145N 30.677915E, matching the stored point north of Lake Qarun) and German Wikipedia (29.59509, 30.67784) both describe Qasr el-Sagha as a single small, unfinished Middle Kingdom temple building (one hall with seven naoi); neither calls it a temple complex, so the most specific canonical type the sources support is Temple.", "value_page": null}]'::jsonb),
